  /* ===========================================================================
   * 7. Studio lighting: key, fill and two strong rim lights (cool white +
   *    cyan/magenta tinted strip). The same rig drives the THREE lights and the
   *    procedural studio environment used for reflections / refraction.
   * ======================================================================== */
  const LIGHTS = {
    key:  { dir: vnorm([-0.55, 0.62, 0.56]), col: [1.00, 0.95, 0.88], I: 2.6 },
    fill: { dir: vnorm([0.78, -0.08, 0.62]), col: [0.76, 0.84, 1.00], I: 0.42 },
    rimA: { dir: vnorm([-0.80, 0.20, -0.56]), col: [0.86, 0.93, 1.00], I: 3.2 },
    rimB: { dir: vnorm([0.82, 0.12, -0.56]), col: [0.58, 0.90, 1.00], I: 2.6 },
  };
  const lc = (l) => vscale(l.col, l.I);
  function boxFrame(c) {
    const u = vnorm(vcross([0, 1, 0], c));
    const v = vcross(c, u);
    return { c, u, v };
  }
  const BOX_KEY = boxFrame(LIGHTS.key.dir), BOX_FILL = boxFrame(LIGHTS.fill.dir);
  const BOX_RIMA = boxFrame(LIGHTS.rimA.dir), BOX_RIMB = boxFrame(LIGHTS.rimB.dir);

  // Seeded offsets for every GLSL noise field (keeps all procedural detail tied to seed 42).
  resetRng();
  const seedVec = () => [rrange(-40, 40), rrange(-40, 40), rrange(-40, 40)];
  const SEEDS = { A: seedVec(), B: seedVec(), C: seedVec(), D: seedVec(), E: seedVec(), F: seedVec() };

  const GLSL_COMMON = `
#define PI 3.141592653589793
const vec3 L_KEY = ${glv3(LIGHTS.key.dir)};  const vec3 C_KEY = ${glv3(lc(LIGHTS.key))};
const vec3 L_FILL = ${glv3(LIGHTS.fill.dir)}; const vec3 C_FILL = ${glv3(lc(LIGHTS.fill))};
const vec3 L_RIMA = ${glv3(LIGHTS.rimA.dir)}; const vec3 C_RIMA = ${glv3(lc(LIGHTS.rimA))};
const vec3 L_RIMB = ${glv3(LIGHTS.rimB.dir)}; const vec3 C_RIMB = ${glv3(lc(LIGHTS.rimB))};
const vec3 C_AMB = vec3(0.012, 0.013, 0.018);
const vec3 KEY_C = ${glv3(BOX_KEY.c)}; const vec3 KEY_U = ${glv3(BOX_KEY.u)}; const vec3 KEY_V = ${glv3(BOX_KEY.v)};
const vec3 FILL_C = ${glv3(BOX_FILL.c)}; const vec3 FILL_U = ${glv3(BOX_FILL.u)}; const vec3 FILL_V = ${glv3(BOX_FILL.v)};
const vec3 RIMA_C = ${glv3(BOX_RIMA.c)}; const vec3 RIMA_U = ${glv3(BOX_RIMA.u)}; const vec3 RIMA_V = ${glv3(BOX_RIMA.v)};
const vec3 RIMB_C = ${glv3(BOX_RIMB.c)}; const vec3 RIMB_U = ${glv3(BOX_RIMB.u)}; const vec3 RIMB_V = ${glv3(BOX_RIMB.v)};
const vec3 E_KEY = vec3(1.00, 0.95, 0.88) * 5.0;
const vec3 E_FILL = vec3(0.75, 0.82, 1.00) * 0.55;
const vec3 E_RIMA = vec3(0.86, 0.93, 1.00) * 7.0;
const vec3 E_RIMB_HI = vec3(0.55, 0.92, 1.00) * 6.0;
const vec3 E_RIMB_LO = vec3(1.00, 0.45, 0.85) * 3.5;
const vec3 E_TOP = vec3(0.90, 0.92, 1.00) * 1.1;
const float EXPOSURE = 1.0;

float boxMask(vec3 d, vec3 c, vec3 u, vec3 v, vec2 hs, float soft) {
  float dc = dot(d, c);
  if (dc <= 0.02) return 0.0;
  vec2 q = vec2(dot(d, u), dot(d, v)) / dc;
  vec2 e = abs(q) - hs;
  float sd = length(max(e, vec2(0.0))) + min(max(e.x, e.y), 0.0);
  return 1.0 - smoothstep(-soft, soft, sd);
}
vec3 envBase(vec3 d) {
  return mix(vec3(0.0030, 0.0033, 0.0045), vec3(0.0105, 0.0112, 0.0140), smoothstep(-0.7, 0.9, d.y));
}
vec3 envLights(vec3 d, float rough) {
  float soft = 0.012 + rough * 0.55;
  vec3 c = E_KEY * boxMask(d, KEY_C, KEY_U, KEY_V, vec2(0.46, 0.32), soft);
  c += E_FILL * boxMask(d, FILL_C, FILL_U, FILL_V, vec2(0.60, 0.45), soft * 1.5 + 0.05);
  float ra = boxMask(d, RIMA_C, RIMA_U, RIMA_V, vec2(0.075, 0.95), soft);
  float rb = boxMask(d, RIMB_C, RIMB_U, RIMB_V, vec2(0.075, 0.95), soft);
  float vb = dot(d, RIMB_V) / max(dot(d, RIMB_C), 0.05);
  c += E_RIMA * ra + mix(E_RIMB_LO, E_RIMB_HI, smoothstep(-0.6, 0.6, vb)) * rb;
  c += E_TOP * boxMask(d, vec3(0.0, 1.0, 0.0), vec3(1.0, 0.0, 0.0), vec3(0.0, 0.0, 1.0), vec2(0.55, 0.10), soft * 1.5);
  return c;
}
vec3 studioEnv(vec3 d, float rough) { return envBase(d) + envLights(d, rough); }
vec3 tmap(vec3 c) { return vec3(1.0) - exp(-max(c, vec3(0.0)) * EXPOSURE); }
vec3 toSRGB(vec3 c) {
  c = clamp(c, 0.0, 1.0);
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c));
}
// Premultiplied output: 'light' is linear radiance added over the backdrop, 'alpha' its occlusion.
vec4 outPremul(vec3 light, float alpha) {
  vec3 c = tmap(light);
  float a = clamp(max(alpha, max(c.r, max(c.g, c.b))), 0.0, 1.0);
  if (a < 0.0004) return vec4(0.0);
  return vec4(toSRGB(c / a) * a, a);
}
float specGGX(vec3 N, vec3 V, vec3 L, float rough) {
  vec3 H = normalize(V + L);
  float NdH = max(dot(N, H), 0.0);
  float NdL = max(dot(N, L), 0.0);
  float NdV = max(dot(N, V), 0.001);
  float a = max(rough * rough, 0.002);
  float a2 = a * a;
  float dd = NdH * NdH * (a2 - 1.0) + 1.0;
  float D = a2 / (PI * dd * dd);
  float k = a * 0.5;
  return D * NdL / (NdL * (1.0 - k) + k) / (NdV * (1.0 - k) + k) * 0.25;
}
float fresnelS(float f0, float c) { return f0 + (1.0 - f0) * pow(1.0 - clamp(c, 0.0, 1.0), 5.0); }
vec3 waterSpec(vec3 N, vec3 V) {
  vec3 s = C_KEY * specGGX(N, V, L_KEY, 0.14) * fresnelS(0.02, dot(V, normalize(V + L_KEY)));
  s += C_RIMA * specGGX(N, V, L_RIMA, 0.16) * fresnelS(0.02, dot(V, normalize(V + L_RIMA)));
  s += C_RIMB * specGGX(N, V, L_RIMB, 0.16) * fresnelS(0.02, dot(V, normalize(V + L_RIMB)));
  s += C_FILL * specGGX(N, V, L_FILL, 0.20) * fresnelS(0.02, dot(V, normalize(V + L_FILL)));
  return s;
}
`;

  // 3D simplex noise (Ashima Arts / Stefan Gustavson, MIT license).
  const GLSL_NOISE = `
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec4 permute(vec4 x) { return mod289(((x * 34.0) + 1.0) * x); }
vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }
float snoise(vec3 v) {
  const vec2 C = vec2(1.0 / 6.0, 1.0 / 3.0);
  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
  vec3 i = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);
  vec3 x1 = x0 - i1 + C.xxx;
  vec3 x2 = x0 - i2 + C.yyy;
  vec3 x3 = x0 - D.yyy;
  i = mod289(i);
  vec4 p = permute(permute(permute(i.z + vec4(0.0, i1.z, i2.z, 1.0)) + i.y + vec4(0.0, i1.y, i2.y, 1.0)) + i.x + vec4(0.0, i1.x, i2.x, 1.0));
  float n_ = 0.142857142857;
  vec3 ns = n_ * D.wyz - D.xzx;
  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_);
  vec4 x = x_ * ns.x + ns.yyyy;
  vec4 y = y_ * ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);
  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);
  vec4 s0 = floor(b0) * 2.0 + 1.0;
  vec4 s1 = floor(b1) * 2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));
  vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
  vec3 p0 = vec3(a0.xy, h.x);
  vec3 p1 = vec3(a0.zw, h.y);
  vec3 p2 = vec3(a1.xy, h.z);
  vec3 p3 = vec3(a1.zw, h.w);
  vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
  m = m * m;
  return 42.0 * dot(m * m, vec4(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));
}
`;

  // Physical model of the water body (pure functions of tau + constants).
  const GLSL_PHYS = `
const float XE = ${glf(XE)};
const float YB = ${glf(YB)};
const float VE = ${glf(VE)};
const float LDRAG = ${glf(LDRAG)};
const float TAU_C = ${glf(TAU_C)};
const float TAU_P = ${glf(TAU_P)};
const float TAU_X = ${glf(TAU_X)};
const float TAU_R = ${glf(TAU_R)};
const float RB = ${glf(RB)};
const float DP = ${glf(DP)};
const float DIMW = ${glf(DIMW)};
const float GRAV = ${glf(GRAV)};
const float CAV_R0 = ${glf(CAV.R0)};
const float CAV_R1 = ${glf(CAV.R1)};
const float CAV_TG = ${glf(CAV.TG)};
const float EXP_MAX = ${glf(EXP.MAX)};
const float EXP_T = ${glf(EXP.T)};
const float TD0 = ${glf(TD0)};
const float TD1 = ${glf(TD1)};
const float RT_MAX = ${glf(RT_MAX)};
const float DOME_H = ${glf(DOME_H)};
const float DOME_W = ${glf(DOME_W)};
const float LIP_K = ${glf(LIP_K)};
const vec3 SEED_A = ${glv3(SEEDS.A)};
const vec3 SEED_C = ${glv3(SEEDS.C)};
const vec3 SEED_D = ${glv3(SEEDS.D)};
const vec3 SEED_E = ${glv3(SEEDS.E)};

float fallAt(float tau) { float d = max(tau - TAU_R, 0.0); return 0.5 * GRAV * d * d; }
float passT(float x) { float D = clamp(XE - x, 0.0, 2.0 * XE + 0.3); return TAU_C + (LDRAG / VE) * (exp(D / LDRAG) - 1.0); }
float axisYRest(float x) { return YB + fallAt(passT(clamp(x, -XE, XE))); }
float cavR(float x, float tau) {
  float D = clamp(XE - x, 0.0, 2.0 * XE + 0.3);
  float tp = TAU_C + (LDRAG / VE) * (exp(D / LDRAG) - 1.0);
  float a = tau - tp;
  if (a <= 0.0) return 0.0;
  float v = exp(-D / LDRAG);
  float rmax = CAV_R0 + CAV_R1 * v * v;
  float r = RB * 1.08 * sqrt(min(a / 0.06, 1.0)) + max(rmax - RB, 0.0) * (1.0 - exp(-a / CAV_TG));
  return r * smoothstep(TAU_P, TAU_P + 0.03, tau);
}
float expandAt(float tau) { float d = max(tau - TAU_X, 0.0); return EXP_MAX * (1.0 - exp(-d / EXP_T)); }
float expandMod(vec3 p) { return 0.78 + 0.45 * snoise(p * 0.9 + SEED_A); }
float dimpleDepthW(float tau) {
  if (tau <= TAU_C) return 0.0;
  if (tau <= TAU_P) return LDRAG * log(1.0 + VE * (tau - TAU_C) / LDRAG);
  return DP * exp(-(tau - TAU_P) / 0.25);
}
float breakTime(vec3 p0) {
  float n = 0.62 * snoise(p0 * 2.0 + SEED_C) + 0.30 * snoise(p0 * 4.6 + SEED_D);
  float ad = length(vec2(p0.y - YB, p0.z));
  float u = clamp(0.40 + 0.80 * n + 0.32 * smoothstep(0.2, 1.3, ad), 0.0, 1.0);
  return TD0 + (TD1 - TD0) * u;
}
// Displaced water-surface point for rest position p0 / rest normal n0 at time tau.
vec3 waterDisp(vec3 p0, vec3 n0, float tau) {
  vec3 p = p0;
  float dd = dimpleDepthW(tau);
  if (dd > 0.0 && p0.x > 0.0) {
    float r0 = length(vec2(p0.y - YB, p0.z));
    float q = max(1.0 - r0 / DIMW, 0.0);
    p.x -= dd * q * q;
  }
  if (p0.x < 0.0 && tau > TAU_X - 0.7) {
    float ay0 = axisYRest(-XE);
    float r1 = length(vec2(p0.y - ay0, p0.z));
    p.x -= DOME_H * smoothstep(TAU_X - 0.7, TAU_X, tau) * exp(-r1 * r1 / (DOME_W * DOME_W));
  }
  float rc = cavR(p.x, tau);
  float ex = expandAt(tau);
  if (rc > 0.0 || ex > 0.0) {
    float ay = axisYRest(p.x);
    vec2 rv = vec2(p.y - ay, p.z);
    float r = length(rv);
    vec2 dir = r > 1e-5 ? rv / r : vec2(0.0, 1.0);
    float em = 0.0;
    if (ex > 0.0) em = ex * mix(1.0, expandMod(p0), smoothstep(0.05, 0.5, r)) * mix(1.0, 0.5, smoothstep(0.35, 1.4, r));
    float rn = sqrt(r * r + rc * rc) + em;
    p.y = ay + dir.x * rn;
    p.z = dir.y * rn;
    float lw = 0.9 * rc + 0.03;
    p.x += sign(p0.x) * LIP_K * rc * exp(-(r * r) / (lw * lw));
  }
  if (tau > TD0 - 1.0) {
    float n = snoise(p0 * 3.4 + SEED_E);
    p += n0 * RT_MAX * smoothstep(TD0 - 1.0, TD1, tau) * pow(max(n, 0.0), 1.5);
  }
  p.y -= fallAt(tau);
  return p;
}
vec3 ballistic(vec3 p0, vec3 v0, float k, float age, out vec3 vel) {
  float e = exp(-k * age);
  vec3 vt = vec3(0.0, -GRAV / k, 0.0);
  vel = vt + (v0 - vt) * e;
  return p0 + vt * age + (v0 - vt) * (1.0 - e) / k;
}
`;

  /*__PART3__*/

