 * ======================================================================== */
const ST = { COUNTDOWN: 'COUNTDOWN', PLAYING: 'PLAYING', PAUSED: 'PAUSED', REFIRE_HOLD: 'REFIRE_HOLD', ENDED: 'ENDED' };
let state = null;              // null until the first animation frame after the initial render
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0;
let holdElapsed = 0;
let lastTs = null;
let needsRender = false;

function showCountdown(n) {
  const txt = String(n);
  if (countdownEl.style.display !== 'block') countdownEl.style.display = 'block';
  if (countdownEl.textContent !== txt) countdownEl.textContent = txt;
}
function hideCountdown() {
  countdownEl.style.display = 'none';
  countdownEl.textContent = '';
}
function setPlayingIcons(playing) {
  iconPause.style.display = playing ? 'block' : 'none';
  iconPlay.style.display = playing ? 'none' : 'block';
