    state = ST.COUNTDOWN;
    countdownElapsed = 0;
    showCountdown(3);
    setPlayingIcons(true);
  } else if (state === ST.COUNTDOWN) {
    countdownElapsed += dtWall;                   // wall clock, independent of playbackSpeed
    if (countdownElapsed >= 3.0) {
      const over = countdownElapsed - 3.0;
      enterPlaying();
      advance(Math.min(over, 0.1));
    } else {
      showCountdown(3 - Math.floor(countdownElapsed));
