 * 13. Playback state machine: COUNTDOWN, PLAYING, PAUSED, REFIRE_HOLD, ENDED
 * ======================================================================== */
const ST = { COUNTDOWN: 'COUNTDOWN', PLAYING: 'PLAYING', PAUSED: 'PAUSED', REFIRE_HOLD: 'REFIRE_HOLD', ENDED: 'ENDED' };
let state = null;              // null until the first animation frame after the initial render
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0;
let holdElapsed = 0;
let lastTs = null;
let needsRender = false;

function showCountdown(n) {
  const txt = String(n);
  if (countdownEl.style.display !== 'block') countdownEl.style.display = 'block';
  if (countdownEl.textContent !== txt) countdownEl.textContent = txt;
}
function hideCountdown() {
  countdownEl.style.display = 'none';
  countdownEl.textContent = '';
}
function setPlayingIcons(playing) {
  iconPause.style.display = playing ? 'block' : 'none';
  iconPlay.style.display = playing ? 'none' : 'block';
  btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function setScrubber() { scrubber.value = simTime.toFixed(3); }
function enterPlaying() { state = ST.PLAYING; hideCountdown(); setPlayingIcons(true); }
function enterPaused() { state = ST.PAUSED; setPlayingIcons(false); }
function enterEnded() { state = ST.ENDED; setPlayingIcons(false); }

function advance(dt) {
  simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
  if (simTime >= DURATION) {
    simTime = DURATION;
    scrubber.value = DURATION.toFixed(3);
    renderAt(simTime);
    needsRender = false;
    enterEnded();
    return;
  }
  setScrubber();
  needsRender = true;
}

function frame(ts) {
  const now = typeof ts === 'number' ? ts : performance.now();
  if (lastTs === null) lastTs = now;
  const dtWall = Math.max(0, (now - lastTs) / 1000);
  lastTs = now;

  if (state === null) {
    // first rAF after the initial resting scene was rendered
    state = ST.COUNTDOWN;
    countdownElapsed = 0;
    showCountdown(3);
    setPlayingIcons(true);
  } else if (state === ST.COUNTDOWN) {
    countdownElapsed += dtWall;                   // wall clock, independent of playbackSpeed
    if (countdownElapsed >= 3.0) {
      const over = countdownElapsed - 3.0;
      enterPlaying();
      advance(Math.min(over, 0.1));
    } else {
      showCountdown(3 - Math.floor(countdownElapsed));
    }
  } else if (state === ST.REFIRE_HOLD) {
    holdElapsed += dtWall;                        // wall clock, independent of playbackSpeed
    if (holdElapsed >= 1.0) {
      const over = holdElapsed - 1.0;
      enterPlaying();
      advance(Math.min(over, 0.1));
    }
  } else if (state === ST.PLAYING) {
    advance(Math.min(dtWall, 0.1));
  }

  if (needsRender) {
    needsRender = false;
    renderAt(simTime);
  }
  requestAnimationFrame(frame);
}

btnToggle.addEventListener('click', () => {
  if (state === ST.PLAYING) {
    enterPaused();
  } else if (state === ST.COUNTDOWN || state === ST.REFIRE_HOLD || state === null) {
    hideCountdown();
    simTime = 0;
    setScrubber();
    renderAt(simTime);
    enterPaused();
  } else if (state === ST.PAUSED) {
    if (simTime >= DURATION) { simTime = 0; setScrubber(); renderAt(simTime); }
    enterPlaying();
  } else if (state === ST.ENDED) {
    simTime = 0;
    setScrubber();
    renderAt(simTime);
    enterPlaying();
  }
});

pills.forEach((pill) => {
  pill.addEventListener('click', () => {
    playbackSpeed = parseFloat(pill.getAttribute('data-speed')) || 1.0;
    pills.forEach((p) => {
      const on = p === pill;
      p.classList.toggle('is-active', on);
      p.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  });
});

function onScrub() {
  if (state === ST.COUNTDOWN || state === ST.REFIRE_HOLD || state === null) hideCountdown();
  const v = parseFloat(scrubber.value);
  simTime = clamp(isFinite(v) ? v : 0, 0, DURATION);
  renderAt(simTime);
  needsRender = false;
  enterPaused();
}
scrubber.addEventListener('input', onScrub);
scrubber.addEventListener('change', onScrub);

btnRefire.addEventListener('click', () => {
  hideCountdown();
  simTime = 0;
  scrubber.value = '0';
  renderAt(0);
  needsRender = false;
  setPlayingIcons(true);
  holdElapsed = 0;
  state = ST.REFIRE_HOLD;
});

window.addEventListener('resize', () => {
  resize();
  renderAt(simTime);
});

/* ===========================================================================
 * 14. Boot: build, render the resting scene at simTime 0, then start the loop
 * ======================================================================== */
try {
  initGraphics();
} catch (err) {
  renderer = null;
  if (window.console) console.warn('WebGL initialisation failed:', err && err.message);
}
renderAt(0);
requestAnimationFrame(frame);

// Read-only hooks for inspection / automated checks.
Object.defineProperty(window, '__balloonSim', {
  value: Object.freeze({
    renderAt,
    tauOf,
    get state() { return state; },
    get simTime() { return simTime; },
    get playbackSpeed() { return playbackSpeed; },
    get particleCount() { return G.particleCount || 0; },
  }),
});

