for (let j = 0; j < S; j++) {
  for (let i = 0; i < S; i++) {
    const x = ((i + 0.5) / S) * 2 - 1, y = 1 - ((j + 0.5) / S) * 2;
    const r = Math.hypot(x, y);
    let R = 0, G = 0, B = 0;
    if (r < 1) {
      const inner = 1 - smoothstep(0.78, 1.0, r);
      const ring = smoothstep(0.42, 0.92, r) * (1 - smoothstep(0.92, 1.0, r));
      // R: cool-white rim light (behind-left): Fresnel edge on the left + refracted crescent on the right
      R = ring * clamp(0.55 - 0.7 * x + 0.15 * y, 0, 1) + 0.55 * Math.exp(-((x - 0.42) ** 2 + (y + 0.05) ** 2) / 0.05) * inner;
      // B: cyan rim light (behind-right), mirrored
      B = ring * clamp(0.55 + 0.7 * x + 0.10 * y, 0, 1) + 0.55 * Math.exp(-((x + 0.42) ** 2 + (y + 0.05) ** 2) / 0.05) * inner;
      // G: specular hot-spot of the key softbox (upper-left) + small secondary glint
      G = Math.exp(-((x + 0.36) ** 2 + (y - 0.40) ** 2) / 0.018) + 0.35 * Math.exp(-((x - 0.30) ** 2 + (y + 0.42) ** 2) / 0.008);
    }
    const k = (j * S + i) * 4;
    img.data[k] = Math.round(255 * clamp(R, 0, 1));
    img.data[k + 1] = Math.round(255 * clamp(G, 0, 1));
    img.data[k + 2] = Math.round(255 * clamp(B, 0, 1));
    img.data[k + 3] = 255;
  }
}

